import * as T from './vendor/three.module.js';
import {GLTFLoader} from './vendor/GLTFLoader.js';
import {clone} from './vendor/SkeletonUtils.js';
import {mergeGeometries} from './vendor/BufferGeometryUtils.js';
const CIVILIANS=['settler','surveyor','engineer','medic','merchant','geologist','builder','carrier','refugee','diplomat','explorer','sailor'];
const loader=new GLTFLoader(),templates={},headMeshes={},clips={};
const names=['male_peasant','male_ranger','female_ranger','head_male','head_female','hair_male','hair_female'];
function mergeOutfit(root){const groups=new Map();root.traverse(m=>{if(!m.isSkinnedMesh)return;const key=m.material.uuid+':'+m.skeleton.uuid+':'+m.name.includes('Head_Hood');if(!groups.has(key))groups.set(key,[]);groups.get(key).push(m);});for(const list of groups.values()){if(list.length<2)continue;const first=list[0];if(list.some(m=>m.matrixWorld.elements.some((v,i)=>Math.abs(v-first.matrixWorld.elements[i])>1e-5)))continue;const parts=list.map(m=>{const g=m.geometry.clone();for(const key of Object.keys(g.attributes))if(!['position','normal','uv','skinIndex','skinWeight'].includes(key))g.deleteAttribute(key);return g;});const geometry=mergeGeometries(parts,false);for(const p of parts)p.dispose();if(!geometry)continue;const mesh=new T.SkinnedMesh(geometry,first.material);mesh.name=first.name;mesh.position.copy(first.position);mesh.quaternion.copy(first.quaternion);mesh.scale.copy(first.scale);mesh.bind(first.skeleton,first.bindMatrix);first.parent.add(mesh);for(const old of list)old.removeFromParent();}}
export const texturedReady=Promise.all(names.map(async name=>{const data=await loader.loadAsync(new URL('./assets/models/'+name+'/model.gltf',import.meta.url).href);templates[name]=data.scene;data.scene.traverse(m=>{if(m.isMesh){m.material.vertexColors=false;}});data.scene.updateMatrixWorld(true);if(!name.startsWith('head_')&&!name.startsWith('hair_'))mergeOutfit(data.scene);})).then(async()=>{const data=await(await fetch(new URL('./assets/models/animations.json',import.meta.url))).json();for(const[name,json]of Object.entries(data))clips[name]=T.AnimationClip.parse(json);});
// A static head is cut from the author's base mesh, in its bind pose, then follows Head.
function makeHead(gender){if(headMeshes[gender])return headMeshes[gender];const root=templates['head_'+gender],origin=root.getObjectByName('Head').getWorldPosition(new T.Vector3()),group=new T.Group();
 root.traverse(mesh=>{if(!mesh.isMesh)return;const geometry=mesh.geometry.clone(),p=geometry.attributes.position,v=new T.Vector3();for(let i=0;i<p.count;i++){v.fromBufferAttribute(p,i);if(mesh.isSkinnedMesh)mesh.applyBoneTransform(i,v);v.applyMatrix4(mesh.matrixWorld).sub(origin);p.setXYZ(i,v.x,v.y,v.z);}const idx=geometry.index?.array||Array.from({length:p.count},(_,i)=>i),keep=[];for(let i=0;i<idx.length;i+=3)if([idx[i],idx[i+1],idx[i+2]].every(j=>p.getY(j)>-.09&&Math.abs(p.getX(j))<.145))keep.push(idx[i],idx[i+1],idx[i+2]);if(!keep.length){geometry.dispose();return;}geometry.setIndex(keep);geometry.deleteAttribute('skinIndex');geometry.deleteAttribute('skinWeight');geometry.computeVertexNormals();geometry.computeBoundingBox();geometry.computeBoundingSphere();const mat=mesh.material.clone();if(mesh.name==='Eyebrows')mat.color.set('#443226');group.add(new T.Mesh(geometry,mat));});
 const hair=templates['hair_'+gender];hair.traverse(mesh=>{if(!mesh.isMesh)return;const geo=mesh.geometry.clone();geo.applyMatrix4(mesh.matrixWorld);geo.translate(-origin.x,-origin.y,-origin.z);const mat=mesh.material.clone();mat.color.set('#493426');const h=new T.Mesh(geo,mat);h.userData.hair=true;group.add(h);});headMeshes[gender]=group;return group;
}
export function importedCharacter(type,era,level,M,part,enemy=false,species='human'){
 if(species!=='human'||!templates.male_peasant||!Object.keys(clips).length||![...CIVILIANS,'spearman','archer','ranger','warden'].includes(type))return null;
 const archer=type==='archer',civil=CIVILIANS.includes(type),gender=archer?'female':'male',body=clone(templates[civil?'male_peasant':archer?'female_ranger':'male_ranger']),root=new T.Group();root.add(body);body.updateMatrixWorld(true);const bones={};body.traverse(n=>{if(n.isBone)bones[n.name]=n;if(n.isMesh){n.castShadow=true;n.receiveShadow=true;n.frustumCulled=false;}});
 const head=makeHead(gender).clone(true),headBone=bones.Head;head.quaternion.copy(headBone.getWorldQuaternion(new T.Quaternion()).invert());headBone.add(head);body.traverse(n=>{if(n.isMesh&&n.name.includes('Head_Hood')&&!archer)n.visible=false;});
 const headPart=(shape,mat,x,y,z,w,h,d,rx=0,ry=0,rz=0)=>part(head,shape,mat,x,y,z,w,h,d,rx,ry,rz);
 if(!civil&&!archer)head.traverse(n=>{if(n.userData.hair)n.visible=false;});
 if(civil){headPart('cylinder',M.canvas,0,.204,0,.22,.02,.2);headPart('cylinder',M.canvas,0,.257,0,.137,.1,.125);headPart('head',M.canvas,0,.305,0,.136,.025,.124);headPart('cylinder',M.leather,0,.215,0,.145,.025,.135);}
 else if(!archer){headPart('heroHair',era>=12?M.army:M.iron,0,.108,0,.115,.126,.115);if(era>=12)headPart('box',M.glass,0,.055,.099,.16,.04,.018);else headPart('box',M.iron,0,.05,.105,.014,.12,.02);}
 const attach=(bone)=>{const p=new T.Group();p.quaternion.copy(bone.getWorldQuaternion(new T.Quaternion()).invert());bone.add(p);return p;},right=attach(bones.hand_r),left=attach(bones.hand_l);let tool=null;
 if(civil){tool=new T.Group();right.add(tool);part(tool,'cylinder',M.wood,0,0,0,.014,.68,.014);part(tool,'chassis',M.iron,0,.31,.015,.2,.12,.035);}
 else if(archer){part(left,'ring',M.wood,0,0,.08,.13,.36,.13,0,Math.PI/2);part(left,'limb',M.cloth,0,0,.08,.008,.35,.008);part(right,'limb',M.wood,0,0,.16,.008,.008,.45);}
 else if(type==='ranger'){part(right,'chassis',M.iron,0,0,.2,.08,.1,.48);part(right,'cylinder',M.black,0,0,.51,.02,.24,.02,Math.PI/2);}
 else{part(right,'cylinder',M.wood,0,.16,0,.015,1.45,.015);part(right,'cone',M.iron,0,.94,0,.05,.16,.04);part(left,'sandbag',M.iron,0,0,.08,.22,.3,.035);part(left,'sandbag',enemy?M.red:M.blue,0,0,.12,.19,.26,.012);part(left,'ball',M.gold,0,0,.14,.05,.05,.025);}
 const load=new T.Group();load.visible=false;const spine=bones.spine_03;spine.add(load);part(load,'sandbag',M.canvas,0,.03,-.14,.18,.24,.12);for(let n=2;n<=level;n++)part(spine,'box',n>=8?M.gold:M.leather,(n%2?1:-1)*.15,-.06+(n%3)*.06,.1,.04,.04,.025);
 const mixer=new T.AnimationMixer(body),actions={};for(const[name,clip]of Object.entries(clips)){const clean=clip.clone();clean.tracks=clean.tracks.filter(t=>!t.name.endsWith('.position')||!t.name.startsWith('root'));actions[name]=mixer.clipAction(clean);}
 body.scale.setScalar(.88);root.userData={type,technology:era,species,enemy,designId:type,characterRevision:14,textured:true,mixer,actions,bones,body,load,tool,gender,phase:0,joints:{body,rightArm:bones.upperarm_r,leftArm:bones.upperarm_l,headPivot:headBone,load,tool}};animateImported(root,{type},0,false,false,false);mixer.update(.25);body.updateMatrixWorld(true);for(const[hand,grip,finger]of[[bones.hand_r,right,bones.middle_01_r],[bones.hand_l,left,bones.middle_01_l]]){grip.quaternion.copy(hand.getWorldQuaternion(new T.Quaternion()).invert());if(finger)grip.position.copy(hand.worldToLocal(finger.getWorldPosition(new T.Vector3()))).multiplyScalar(.6);}return root;
}
export function animateImported(g,u,time,moving,working,carrying){const d=g.userData;if(!d.textured)return false;const keys=Object.keys(d.actions),find=(names)=>names.find(n=>d.actions[n])||keys.find(n=>n.includes('Idle'))||keys[0],name=working?find(u.gatherResource==='food'?['Farm_Harvest','Farm_PlantSeed']:['TreeChopping_Loop','Farm_Harvest']):u.cooldown>.8?find(['Sword_Regular_A','Melee_Hook']):moving?find(carrying?['Walk_Carry_Loop','Walking_Loop']:['Walking_Loop','Walk_Loop','Walk_Carry_Loop']):find(['Idle_Loop','Idle_No_Loop','Idle_Shield_Loop']);if(name!==d.active){d.actions[d.active]?.fadeOut(.12);d.actions[name].reset().fadeIn(.12).play();d.active=name;}const delta=Math.max(0,Math.min(.1,time-(d.lastTime??time-.033)));d.lastTime=time;d.mixer.update(delta);d.load.visible=carrying;if(d.tool)d.tool.visible=!working||!['food','water'].includes(u.gatherResource);g.updateMatrixWorld(true);return true;}
